1	package shadow
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"sort"
7		"time"
8	)
9	
10	// 升级阶段标识。
11	const (
12		StageDownload = "download"
13		StageInstall  = "install"
14		StageRollback = "rollback"
15	)
16	
17	// 活动与设备在活动中的状态。
18	const (
19		CampaignRunning   = "running"
20		CampaignSucceeded = "succeeded"
21		CampaignFailed    = "failed"
22	
23		DevicePending     = "pending"     // 尚未领取下载
24		DeviceDownloading = "downloading" // 已领取下载，未完成
25		DeviceReady       = "ready"       // 下载成功，安装尚未领取
26		DeviceInstalling  = "installing"  // 已领取安装，未完成
27		DeviceSucceeded   = "succeeded"
28		DeviceFailed      = "failed"
29		DeviceTimeout     = "timeout"
30		DeviceSkipped     = "skipped" // 前序批次失败后，后续批次记为未执行
31	
32		// 回滚相关状态，仅出现在开启回滚的活动中。
33		DeviceAwaitingRollback  = "awaiting_rollback" // 安装失败已接受，等待领取回滚
34		DeviceRollingBack       = "rolling_back"      // 已领取回滚，未完成
35		DeviceRollbackSucceeded = "rollback_succeeded"
36		DeviceRollbackFailed    = "rollback_failed"
37		DeviceRollbackTimeout   = "rollback_timeout" // 到达截止时间时回滚仍未完成
38	)
39	
40	// VersionSpec 是一个已登记的升级目标版本及其允许的当前版本。
41	type VersionSpec struct {
42		// Target 是目标版本，与设备当前版本按字符串精确匹配。
43		Target string
44		// AllowedFrom 是允许升级到目标版本的当前版本列表。
45		AllowedFrom []string
46	}
47	
48	// versionState 是升级版本登记的内部状态。
49	type versionState struct {
50		Target      string
51		AllowedFrom []string
52	}
53	
54	// CampaignSpec 描述创建分批升级活动所需的全部信息。
55	type CampaignSpec struct {
56		// ID 是活动唯一标识，不能为空。
57		ID string
58		// Operator 是创建活动的操作者，不能为空。
59		Operator string
60		// CreatedAt 是活动创建时间。
61		CreatedAt time.Time
62		// TargetVersion 是已登记的目标版本。
63		TargetVersion string
64		// Devices 是按提交次序排列的有序设备列表，不能为空、不能重复。
65		Devices []string
66		// BatchSize 是批大小，必须是正整数。
67		BatchSize int
68		// WindowStart/WindowEnd 是维护窗口，开始时刻须早于结束时刻；
69		// 窗口包含开始时刻、不包含结束时刻。
70		WindowStart time.Time
71		WindowEnd   time.Time
72		// Deadline 是截止时间，必须晚于创建时间。
73		Deadline time.Time
74		// RollbackOnFailure 开启安装失败后的自动回滚，默认关闭。
75		// 关闭时安装失败即设备失败；开启后安装失败会先等待设备回滚到
76		// 首次领取下载时锁定的当前版本，活动最终仍为失败。
77		RollbackOnFailure bool
78	}
79	
80	// Operation 是派发给设备的一个升级操作。
81	type Operation struct {
82		// ID 是操作的稳定标识，重复查询未完成操作时保持不变，重开存储后仍有效。
83		ID         string
84		CampaignID string
85		DeviceID   string
86		// Kind 是 StageDownload、StageInstall 或 StageRollback。
87		Kind string
88		// TargetVersion 仅在回滚操作上有值，指明必须恢复到的锁定版本，
89		// 让设备明确知道要恢复哪个版本；下载与安装操作为空。
90		TargetVersion string
91	}
92	
93	// OperationResult 是设备提交的一次操作结果。
94	// 每次结果必须带活动、设备、操作标识及发生时间。
95	// 安装成功（Success 且操作是 install）时还须附带符合上报规则的设备上报：
96	// 正整数 Seq、等于目标版本的 Version 和完整 JSON 对象 Config。
97	// 回滚成功（Success 且操作是 rollback）时同样须附带上报，
98	// 但 Version 必须等于领取下载时锁定的回滚目标版本。
99	type OperationResult struct {
100		CampaignID  string
101		DeviceID    string
102		OperationID string
103		At          time.Time
104		Success     bool
105		// Reason 在失败时必填。
106		Reason string
107		// 安装成功时附带的设备上报。
108		Seq     uint64
109		Version string
110		Config  json.RawMessage
111	}
112	
113	// ResultRecord 是结果历史中的一条记录，按接受顺序保存。
114	type ResultRecord struct {
115		DeviceID    string
116		OperationID string
117		Stage       string
118		Success     bool
119		Reason      string
120		// Version 为安装或回滚成功时上报的版本，其余为空。
121		Version string
122		At      time.Time
123	}
124	
125	// opState 是单个设备单个阶段的操作与结果状态。
126	type opState struct {
127		ID string
128		// Claimed 表示操作是否已被领取；未领取的操作不能提交结果。
129		Claimed   bool
130		ClaimedAt time.Time
131		// 已接受的结果。
132		HasResult     bool
133		Success       bool
134		Reason        string
135		At            time.Time
136		ResultSeq     uint64
137		ResultVersion string
138		ResultConfig  json.RawMessage
139	}
140	
141	// campaignDevice 是单台设备在一个活动中的完整状态。
142	type campaignDevice struct {
143		DeviceID string
144		Batch    int
145		Download opState
146		Install  opState
147		// Rollback 是安装失败后的回滚操作，仅在开启回滚的活动中使用。
148		Rollback opState
149		// RollbackTarget 是首次领取下载时锁定的设备当前版本，回滚必须恢复到它。
150		// 后续普通上报不改变它，也不要求它另行登记为升级目标。
151		RollbackTarget string
152		// Status/Phase/Reason/At 描述设备当前状态；
153		// failed 必须记录阶段、原因和时间；timeout/skipped 同理。
154		Status string
155		Phase  string
156		Reason string
157		At     time.Time
158	}
159	
160	// campaignState 是一个分批升级活动的内部状态。
161	type campaignState struct {
162		ID          string
163		Operator    string
164		Target      string
165		CreatedAt   time.Time
166		BatchSize   int
167		WindowStart time.Time
168		WindowEnd   time.Time
169		Deadline    time.Time
170		// RollbackOnFailure 表示安装失败后是否进入回滚；旧存储缺省为关闭。
171		RollbackOnFailure bool
172		Devices           []*campaignDevice
173		index             map[string]int
174		Results           []ResultRecord
175		// LastTime 是本活动已接受的最晚时间，用于拒绝时间倒退。
176		LastTime time.Time
177		Status   string
178		Ended    bool
179		EndedAt  time.Time
180	}
181	
182	// RegisterUpgrade 登记一个升级目标版本及允许升级的当前版本列表。
183	// 版本字符串精确匹配；列表不能为空、不能含空串、不能包含目标版本。
184	// 目标版本重复登记时返回 ErrVersionExists 并保留原记录。
185	func (s *Store) RegisterUpgrade(targetVersion string, allowedFrom []string) error {
186		s.mu.Lock()
187		defer s.mu.Unlock()
188		if err := s.checkOpen(); err != nil {
189			return err
190		}
191		if targetVersion == "" {
192			return ErrInvalidVersion
193		}
194		if err := validateAllowedFrom(targetVersion, allowedFrom); err != nil {
195			return err
196		}
197		if _, ok := s.versions[targetVersion]; ok {
198			return fmt.Errorf("%w: %s", ErrVersionExists, targetVersion)
199		}
200		from := append([]string(nil), allowedFrom...)
201		return s.commit(func() error {
202			s.versions[targetVersion] = &versionState{Target: targetVersion, AllowedFrom: from}
203			return nil
204		})
205	}
206	
207	func validateAllowedFrom(target string, allowedFrom []string) error {
208		if len(allowedFrom) == 0 {
209			return fmt.Errorf("%w: list is empty", ErrInvalidVersionList)
210		}
211		for _, v := range allowedFrom {
212			if v == "" {
213				return fmt.Errorf("%w: contains empty version", ErrInvalidVersionList)
214			}
215			if v == target {
216				return fmt.Errorf("%w: contains target version %s", ErrInvalidVersionList, target)
217			}
218		}
219		return nil
220	}
221	
222	// CreateCampaign 创建分批升级活动。任何必填信息缺失、设备或目标版本未登记、
223	// 设备当前版本不兼容或设备已参加未结束活动时，整次创建失败，不留下部分记录。
224	func (s *Store) CreateCampaign(spec CampaignSpec) error {
225		s.mu.Lock()
226		defer s.mu.Unlock()
227		if err := s.checkOpen(); err != nil {
228			return err
229		}
230		// 先做全部校验，全部通过后才写入，保证原子创建。
231		if spec.ID == "" {
232			return ErrInvalidCampaignID
233		}
234		if spec.Operator == "" {
235			return ErrInvalidOperator
236		}
237		if spec.CreatedAt.IsZero() {
238			return fmt.Errorf("%w: created at", ErrInvalidTime)
239		}
240		if spec.WindowStart.IsZero() || spec.WindowEnd.IsZero() {
241			return fmt.Errorf("%w: maintenance window", ErrInvalidTime)
242		}
243		if spec.Deadline.IsZero() {
244			return fmt.Errorf("%w: deadline", ErrInvalidTime)
245		}
246		if len(spec.Devices) == 0 {
247			return ErrInvalidDeviceList
248		}
249		seen := make(map[string]bool, len(spec.Devices))
250		for _, id := range spec.Devices {
251			if id == "" {
252				return ErrInvalidDeviceID
253			}
254			if seen[id] {
255				return fmt.Errorf("%w: %s", ErrDuplicateDevice, id)
256			}
257			seen[id] = true
258		}
259		if spec.BatchSize <= 0 {
260			return ErrInvalidBatchSize
261		}
262		if !spec.WindowStart.Before(spec.WindowEnd) {
263			return ErrInvalidWindow
264		}
265		if !spec.Deadline.After(spec.CreatedAt) {
266			return ErrInvalidDeadline
267		}
268		if spec.TargetVersion == "" {
269			return ErrInvalidVersion
270		}
271		if _, ok := s.versions[spec.TargetVersion]; !ok {
272			return fmt.Errorf("%w: %s", ErrVersionNotFound, spec.TargetVersion)
273		}
274		if _, ok := s.campaigns[spec.ID]; ok {
275			return fmt.Errorf("%w: %s", ErrCampaignExists, spec.ID)
276		}
277		ver := s.versions[spec.TargetVersion]
278		devs := make([]*campaignDevice, 0, len(spec.Devices))
279		for i, id := range spec.Devices {
280			d, ok := s.devices[id]
281			if !ok {
282				return fmt.Errorf("%w: %s", ErrDeviceNotFound, id)
283			}
284			if !containsString(ver.AllowedFrom, d.Version) {
285				return fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, id, d.Version)
286			}
287			if s.deviceBusy(id, spec.ID) {
288				return fmt.Errorf("%w: %s", ErrDeviceBusy, id)
289			}
290			devs = append(devs, &campaignDevice{
291				DeviceID: id,
292				Batch:    i / spec.BatchSize,
293				Status:   DevicePending,
294				Phase:    StageDownload,
295				Download: opState{ID: operationID(spec.ID, id, StageDownload)},
296				Install:  opState{ID: operationID(spec.ID, id, StageInstall)},
297				Rollback: opState{ID: operationID(spec.ID, id, StageRollback)},
298			})
299		}
300		campaign := &campaignState{
301			ID:                spec.ID,
302			Operator:          spec.Operator,
303			Target:            spec.TargetVersion,
304			CreatedAt:         spec.CreatedAt,
305			BatchSize:         spec.BatchSize,
306			WindowStart:       spec.WindowStart,
307			WindowEnd:         spec.WindowEnd,
308			Deadline:          spec.Deadline,
309			RollbackOnFailure: spec.RollbackOnFailure,
310			Devices:           devs,
311			index:             make(map[string]int, len(devs)),
312			LastTime:          spec.CreatedAt,
313			Status:            CampaignRunning,
314		}
315		for i, cd := range devs {
316			campaign.index[cd.DeviceID] = i
317		}
318		return s.commit(func() error {
319			s.campaigns[spec.ID] = campaign
320			return nil
321		})
322	}
323	
324	// deviceBusy 判断设备是否已参加另一个尚未结束的活动。
325	func (s *Store) deviceBusy(deviceID, excludeCampaign string) bool {
326		for id, c := range s.campaigns {
327			if id == excludeCampaign || c.Ended {
328				continue
329			}
330			if _, ok := c.index[deviceID]; ok {
331				return true
332			}
333		}
334		return false
335	}
336	
337	func operationID(campaignID, deviceID, stage string) string {
338		return campaignID + ":" + deviceID + ":" + stage
339	}
340	
341	func containsString(list []string, v string) bool {
342		for _, x := range list {
343			if x == v {
344				return true
345			}
346		}
347		return false
348	}
349	
350	// Claim 由调用方传入当前时间，为活动中的设备领取当前可执行的操作。
351	//
352	// 派发新的下载或安装操作要求设备在线、当前时间位于维护窗口 [start, end) 内、
353	// 所在批次已被前一批全部成功放行。首次领取下载前会再次核对设备当前版本，
354	// 不兼容则将该设备（带阶段、原因和时间）记为失败，返回 ErrIncompatibleVersion；
355	// 开启回滚的活动还会在首次领取下载时把设备当时的当前版本锁定为回滚目标，
356	// 后续普通上报不改变它。
357	// 开启回滚且安装失败已被接受后，设备领取回滚操作：首次领取同样要求设备在线
358	// 且时间位于原维护窗口 [start, end) 内（不受批次放行影响），返回的操作带锁定
359	// 目标版本；离线或窗口外保留待办。回滚已领取但未完成时再次查询返回同一标识，
360	// 且可在窗口外、截止前提交结果。
361	// 已领取但未完成的操作（下载/安装/回滚）再次查询时返回同一标识，不要求在线或位于窗口内。
362	// 离线设备保留待办；离线或窗口外暂无可领取的新操作时返回 (nil, nil)。
363	// 时间缺失或相对本活动已接受的时间倒退时拒绝，且不改变状态。
364	func (s *Store) Claim(campaignID, deviceID string, at time.Time) (*Operation, error) {
365		s.mu.Lock()
366		defer s.mu.Unlock()
367		if err := s.checkOpen(); err != nil {
368			return nil, err
369		}
370		c, cd, err := s.lookupCampaignDevice(campaignID, deviceID)
371		if err != nil {
372			return nil, err
373		}
374		if at.IsZero() {
375			return nil, ErrInvalidTime
376		}
377		if at.Before(c.LastTime) {
378			return nil, fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
379		}
380		var op *Operation
381		var reject error
382		err = s.commit(func() error {
383			// 到达截止时间：未结束设备全部超时并落盘，本次领取拒绝。
384			// 即使查询的设备已有终态，其他未结束设备仍要级联超时。
385			if !at.Before(c.Deadline) {
386				c.LastTime = at
387				s.applyTimeout(c, at)
388				reject = ErrCampaignEnded
389				return nil
390			}
391			if c.Ended {
392				// 纯拒绝路径：不推进时间基线，不改状态。
393				reject = ErrCampaignEnded
394				return nil
395			}
396			if isTerminal(cd.Status) {
397				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, deviceID)
398				return nil
399			}
400			c.LastTime = at
401			// 已领取但未完成的操作：查询仍返回原标识，不要求在线或位于窗口内。
402			if out := outstandingOp(c, cd); out != nil {
403				op = out
404				return nil
405			}
406			// 安装失败已接受、等待回滚：回滚是该设备的善后操作，不受批次放行影响。
407			// 首次领取要求在线且位于原维护窗口 [start,end) 内；离线或窗口外保留待办。
408			if cd.Status == DeviceAwaitingRollback {
409				if !s.devices[deviceID].Online {
410					return nil
411				}
412				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
413					return nil
414				}
415				cd.Rollback.Claimed = true
416				cd.Rollback.ClaimedAt = at
417				cd.Status = DeviceRollingBack
418				cd.Phase = StageRollback
419				cd.At = at
420				op = &Operation{
421					ID:            cd.Rollback.ID,
422					CampaignID:    c.ID,
423					DeviceID:      deviceID,
424					Kind:          StageRollback,
425					TargetVersion: cd.RollbackTarget,
426				}
427				return nil
428			}
429			// 尚未领取的新阶段：先看批次是否放行（不放行时无操作可领）。
430			if !s.batchOpen(c, cd) {
431				return nil
432			}
433			if !s.devices[deviceID].Online {
434				return nil // 离线保留待办，上线后继续
435			}
436			if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
437				return nil // 窗口外不派发新操作；窗口为 [start, end)
438			}
439			if !cd.Download.Claimed {
440				// 首次领取下载前再次检查当前版本。
441				current := s.devices[deviceID].Version
442				if !containsString(s.versions[c.Target].AllowedFrom, current) {
443					reason := fmt.Sprintf("version %s is not compatible with target %s", current, c.Target)
444					// 该设备在下载阶段失败：领取即触发，记录阶段、原因和时间。
445					cd.Download.Claimed = true
446					cd.Download.ClaimedAt = at
447					cd.Download.HasResult = true
448					cd.Download.Success = false
449					cd.Download.Reason = reason
450					cd.Download.At = at
451					s.failDevice(c, cd, StageDownload, reason, at)
452					reject = fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, deviceID, current)
453					return nil
454				}
455				// 开启回滚时，把首次领取下载时设备的当前版本锁定为回滚目标；
456				// 此后普通上报不改变它，也不要求该版本另行登记为升级目标。
457				if c.RollbackOnFailure && cd.RollbackTarget == "" {
458					cd.RollbackTarget = current
459				}
460				cd.Download.Claimed = true
461				cd.Download.ClaimedAt = at
462				cd.Status = DeviceDownloading
463				cd.At = at
464				op = &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageDownload}
465				return nil
466			}
467			// 下载已成功：领取安装（尚未领取的安装仍须在线且位于窗口内）。
468			cd.Install.Claimed = true
469			cd.Install.ClaimedAt = at
470			cd.Status = DeviceInstalling
471			cd.At = at
472			op = &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageInstall}
473			return nil
474		})
475		if err != nil {
476			return nil, err
477		}
478		if reject != nil {
479			return nil, reject
480		}
481		return op, nil
482	}
483	
484	// outstandingOp 返回设备已领取但尚无结果的操作；没有则返回 nil。
485	func outstandingOp(c *campaignState, cd *campaignDevice) *Operation {
486		switch {
487		case cd.Download.Claimed && !cd.Download.HasResult:
488			return &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageDownload}
489		case cd.Install.Claimed && !cd.Install.HasResult:
490			return &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageInstall}
491		case cd.Rollback.Claimed && !cd.Rollback.HasResult:
492			// 已领取但未完成的回滚再次领取仍返回同一标识，并继续告知恢复目标版本。
493			return &Operation{
494				ID:            cd.Rollback.ID,
495				CampaignID:    c.ID,
496				DeviceID:      cd.DeviceID,
497				Kind:          StageRollback,
498				TargetVersion: cd.RollbackTarget,
499			}
500		default:
501			return nil
502		}
503	}
504	
505	// batchOpen 判断设备所在批次是否已放行：前序所有设备必须全部成功。
506	func (s *Store) batchOpen(c *campaignState, cd *campaignDevice) bool {
507		for _, other := range c.Devices {
508			if other.Batch < cd.Batch && other.Status != DeviceSucceeded {
509				return false
510			}
511		}
512		return true
513	}
514	
515	// SubmitResult 接收设备提交的操作结果。
516	//
517	// 相同操作的相同结果重复提交返回成功，但不增加历史、不重复放行批次；
518	// 改用不同结果、跳过未领取阶段、提交未领取的回滚、提交其他设备的操作、
519	// 活动结束后的新结果均报错且不改变状态；已接受结果的重复提交在活动结束后仍有效。
520	// 下载完成后才能领取并安装；设备失败记录阶段、原因和时间，同批其他设备
521	// 继续完成，后续批次记为未执行。安装成功须附带版本等于目标版本的合规上报，
522	// 回滚成功须附带版本等于锁定回滚目标的合规上报，影子与活动在同一次持久化中更新。
523	// 开启回滚的活动中，安装失败不直接结束设备，而是保留原失败原因与时间、
524	// 令设备等待回滚；回滚失败必须给出原因，设备以回滚失败结束且影子不变。
525	// 已领取且尚未接受结果的操作在截止时刻及以后提交时，结果已经迟到：
526	// 不校验附带上报与失败原因、不接收为操作结果，直接按截止处理——未结束设备
527	// 全部超时（等待或正在回滚的记回滚超时），活动以失败结束，返回 ErrCampaignEnded。
528	// 普通设备上报不经过本方法，也不会推进活动。
529	func (s *Store) SubmitResult(res OperationResult) error {
530		s.mu.Lock()
531		defer s.mu.Unlock()
532		if err := s.checkOpen(); err != nil {
533			return err
534		}
535		c, cd, err := s.lookupCampaignDevice(res.CampaignID, res.DeviceID)
536		if err != nil {
537			return err
538		}
539		if res.At.IsZero() {
540			return ErrInvalidTime
541		}
542		// 定位操作标识所属阶段；不属于本设备的操作一律视为未知。
543		var stage string
544		var op *opState
545		switch res.OperationID {
546		case cd.Download.ID:
547			stage, op = StageDownload, &cd.Download
548		case cd.Install.ID:
549			stage, op = StageInstall, &cd.Install
550		case cd.Rollback.ID:
551			stage, op = StageRollback, &cd.Rollback
552		default:
553			return fmt.Errorf("%w: %s", ErrOperationNotFound, res.OperationID)
554		}
555		// 已接受结果：相同结果幂等（活动结束后仍有效，不增加历史、不重复放行），
556		// 不推进时间基线；不同结果冲突。均不改变状态。
557		if op.HasResult {
558			if resultMatches(op, res) {
559				return nil
560			}
561			return fmt.Errorf("%w: operation %s", ErrResultConflict, res.OperationID)
562		}
563		if res.At.Before(c.LastTime) {
564			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, res.At, c.LastTime)
565		}
566		if !op.Claimed {
567			// 标识是本设备未来阶段的操作但尚未领取：属于跳过阶段（含未领取的回滚）。
568			return fmt.Errorf("%w: %s", ErrOperationNotClaimed, res.OperationID)
569		}
570		// 已领取且尚未接受结果的操作在截止时刻及以后提交：结果已经迟到，
571		// 不再接收为操作结果，也不校验附带上报或失败原因——直接按截止处理：
572		// 未结束设备全部超时（等待/正在回滚的记回滚超时），活动以失败结束，
573		// 状态时间与活动结束时间采用本次提交时间，返回 ErrCampaignEnded。
574		if !c.Ended && !res.At.Before(c.Deadline) {
575			if err := s.commit(func() error {
576				c.LastTime = res.At
577				s.applyTimeout(c, res.At)
578				return nil
579			}); err != nil {
580				return err
581			}
582			return ErrCampaignEnded
583		}
584		if !res.Success && res.Reason == "" {
585			return ErrInvalidReason
586		}
587		if res.Success && (stage == StageInstall || stage == StageRollback) {
588			// 安装上报版本必须等于升级目标；回滚上报版本必须等于锁定的回滚目标。
589			wantVersion := c.Target
590			if stage == StageRollback {
591				wantVersion = cd.RollbackTarget
592			}
593			if err := s.validateSuccessReport(res, wantVersion); err != nil {
594				return err
595			}
596		}
597		var reject error
598		err = s.commit(func() error {
599			// 活动已结束且提交时间越过截止时间：只推进时间基线并拒绝
600			// （未结束活动的截止处理已在提交前完成，不会到达这里）。
601			if !res.At.Before(c.Deadline) {
602				c.LastTime = res.At
603				s.applyTimeout(c, res.At)
604				reject = ErrCampaignEnded
605				return nil
606			}
607			if c.Ended {
608				// 活动结束后的新结果：拒绝且不改状态（重复结果已在提交前处理）。
609				reject = ErrCampaignEnded
610				return nil
611			}
612			if isTerminal(cd.Status) {
613				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, res.DeviceID)
614				return nil
615			}
616			c.LastTime = res.At
617			op.HasResult = true
618			op.Success = res.Success
619			op.Reason = res.Reason
620			op.At = res.At
621			if !res.Success {
622				switch {
623				case stage == StageInstall && c.RollbackOnFailure:
624					// 安装失败：保留原因和时间，设备转入等待回滚（非终态）；
625					// 同批其他设备继续，后续批次立即记为未执行，活动暂不结束。
626					s.enterRollback(c, cd, res.Reason, res.At)
627				case stage == StageRollback:
628					// 回滚失败必须给出原因：设备以回滚失败结束且影子不变。
629					s.finishRollbackFailure(c, cd, res.Reason, res.At)
630				default:
631					s.failDevice(c, cd, stage, res.Reason, res.At)
632				}
633				return nil
634			}
635			switch stage {
636			case StageDownload:
637				cd.Status = DeviceReady
638				cd.Phase = StageInstall
639				cd.Reason = ""
640				cd.At = res.At
641			case StageInstall:
642				// 安装成功：附带上报与活动同时更新、一起持久化。
643				s.applySuccessReport(cd.DeviceID, res, res.At)
644				op.ResultSeq = res.Seq
645				op.ResultVersion = res.Version
646				op.ResultConfig = cloneRaw(res.Config)
647				cd.Status = DeviceSucceeded
648				cd.Phase = StageInstall
649				cd.Reason = ""
650				cd.At = res.At
651			case StageRollback:
652				// 回滚成功：按上报规则更新影子（版本回到锁定目标），同时推进回滚状态。
653				// 期望配置、修订号与审计保持不变。
654				s.applySuccessReport(cd.DeviceID, res, res.At)
655				op.ResultSeq = res.Seq
656				op.ResultVersion = res.Version
657				op.ResultConfig = cloneRaw(res.Config)
658				cd.Status = DeviceRollbackSucceeded
659				cd.Phase = StageRollback
660				cd.Reason = ""
661				cd.At = res.At
662			}
663			c.Results = append(c.Results, ResultRecord{
664				DeviceID:    cd.DeviceID,
665				OperationID: op.ID,
666				Stage:       stage,
667				Success:     true,
668				Version:     op.ResultVersion,
669				At:          res.At,
670			})
671			s.settle(c, res.At)
672			return nil
673		})
674		if err != nil {
675			return err
676		}
677		return reject
678	}
679	
680	// resultMatches 判断提交是否为已接受结果的重复提交（同一操作、相同结果）。
681	// 安装成功结果还须附带相同的上报（序号、版本、配置）；发生时间不参与判定，
682	// 使活动结束后的重复提交仍然有效。
683	func resultMatches(op *opState, res OperationResult) bool {
684		if op.Success != res.Success || op.Reason != res.Reason {
685			return false
686		}
687		if op.Success && op.ResultSeq != 0 {
688			return op.ResultSeq == res.Seq &&
689				op.ResultVersion == res.Version &&
690				rawEqual(op.ResultConfig, res.Config)
691		}
692		return true
693	}
694	
695	// validateSuccessReport 按现有上报规则校验安装/回滚成功附带的设备上报，
696	// 且版本必须等于 wantVersion（安装为升级目标，回滚为锁定目标）。只校验，不改状态。
697	func (s *Store) validateSuccessReport(res OperationResult, wantVersion string) error {
698		d := s.devices[res.DeviceID]
699		if res.Seq == 0 {
700			return fmt.Errorf("%w: report sequence", ErrInvalidReport)
701		}
702		if res.Version == "" {
703			return fmt.Errorf("%w: report version", ErrInvalidReport)
704		}
705		if res.Version != wantVersion {
706			return fmt.Errorf("%w: version %s", ErrInvalidReport, res.Version)
707		}
708		if _, err := validateConfig(res.Config); err != nil {
709			return fmt.Errorf("%w: config", ErrInvalidReport)
710		}
711		switch {
712		case res.Seq < d.LastSeq:
713			return fmt.Errorf("%w: stale sequence", ErrInvalidReport)
714		case res.Seq == d.LastSeq:
715			if !(res.Version == d.Version && res.At.Equal(d.LastReportTime) && rawEqual(res.Config, d.Reported)) {
716				return fmt.Errorf("%w: sequence conflict", ErrInvalidReport)
717			}
718		}
719		return nil
720	}
721	
722	// applySuccessReport 按 Report 的既有规则写入影子（调用方已校验）。
723	// 只更新上报侧（版本、上报配置、序号、在线状态与配置差异），
724	// 不动期望配置、修订号与审计。
725	func (s *Store) applySuccessReport(deviceID string, res OperationResult, at time.Time) {
726		d := s.devices[deviceID]
727		if res.Seq == d.LastSeq {
728			// 相同序号的完全重复上报：影子不变，只随活动一起落盘。
729			return
730		}
731		d.Reported = cloneRaw(res.Config)
732		d.Version = res.Version
733		d.Online = true
734		d.LastSeq = res.Seq
735		d.LastReportTime = at
736		d.refreshDiff(at)
737	}
738	
739	// enterRollback 在开启回滚的活动中处理已接受的安装失败：
740	// 保留原安装失败的原因与时间，令设备等待回滚（非终态）；
741	// 同批其他设备可继续，后续批次立即记为未执行，但活动暂不结束。
742	func (s *Store) enterRollback(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
743		cd.Status = DeviceAwaitingRollback
744		cd.Phase = StageRollback
745		cd.Reason = reason
746		cd.At = at
747		c.Results = append(c.Results, ResultRecord{
748			DeviceID:    cd.DeviceID,
749			OperationID: cd.Install.ID,
750			Stage:       StageInstall,
751			Success:     false,
752			Reason:      reason,
753			At:          at,
754		})
755		skipLaterBatches(c, cd, at)
756		// 不结束活动：设备进入非终态的等待回滚，活动要等其回滚结束。
757	}
758	
759	// finishRollbackFailure 处理已接受的回滚失败：必须给出原因，
760	// 设备以回滚失败结束，影子不变（失败结果不附带、不应用上报）。
761	func (s *Store) finishRollbackFailure(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
762		cd.Status = DeviceRollbackFailed
763		cd.Phase = StageRollback
764		cd.Reason = reason
765		cd.At = at
766		c.Results = append(c.Results, ResultRecord{
767			DeviceID:    cd.DeviceID,
768			OperationID: cd.Rollback.ID,
769			Stage:       StageRollback,
770			Success:     false,
771			Reason:      reason,
772			At:          at,
773		})
774		s.settle(c, at)
775	}
776	
777	// skipLaterBatches 把后续批次中尚未结束的设备立即记为未执行。
778	func skipLaterBatches(c *campaignState, cd *campaignDevice, at time.Time) {
779		for _, other := range c.Devices {
780			if other.Batch > cd.Batch && !isTerminal(other.Status) {
781				other.Status = DeviceSkipped
782				other.Phase = pendingPhase(other)
783				other.Reason = "not executed: previous batch failed"
784				other.At = at
785			}
786		}
787	}
788	
789	// failDevice 将设备记为失败，记录阶段、原因和时间；后续批次全部记为未执行，
790	// 本批其他设备继续。若全部设备已到终态，则活动以失败结束。
791	func (s *Store) failDevice(c *campaignState, cd *campaignDevice, phase, reason string, at time.Time) {
792		cd.Status = DeviceFailed
793		cd.Phase = phase
794		cd.Reason = reason
795		cd.At = at
796		c.Results = append(c.Results, ResultRecord{
797			DeviceID:    cd.DeviceID,
798			OperationID: opIDFor(cd, phase),
799			Stage:       phase,
800			Success:     false,
801			Reason:      reason,
802			At:          at,
803		})
804		skipLaterBatches(c, cd, at)
805		s.settle(c, at)
806	}
807	
808	func opIDFor(cd *campaignDevice, phase string) string {
809		switch phase {
810		case StageInstall:
811			return cd.Install.ID
812		case StageRollback:
813			return cd.Rollback.ID
814		default:
815			return cd.Download.ID
816		}
817	}
818	
819	// pendingPhase 返回设备尚未完成的阶段：下载成功后停留在安装阶段。
820	func pendingPhase(cd *campaignDevice) string {
821		if cd.Download.HasResult && cd.Download.Success {
822			return StageInstall
823		}
824		return StageDownload
825	}
826	
827	// applyTimeout 在当前时间达到截止时间时，把所有未结束设备记为超时，
828	// 已有终态保持不变，活动记为失败并结束。等待回滚或正在回滚的设备
829	// 以回滚阶段超时结束；不改写或清空影子。
830	func (s *Store) applyTimeout(c *campaignState, at time.Time) {
831		if c.Ended {
832			return
833		}
834		for _, cd := range c.Devices {
835			if isTerminal(cd.Status) {
836				continue
837			}
838			switch cd.Status {
839			case DeviceAwaitingRollback, DeviceRollingBack:
840				cd.Status = DeviceRollbackTimeout
841				cd.Phase = StageRollback
842			default:
843				cd.Status = DeviceTimeout
844				cd.Phase = pendingPhase(cd)
845			}
846			cd.Reason = "deadline exceeded"
847			cd.At = at
848		}
849		c.Status = CampaignFailed
850		c.Ended = true
851		c.EndedAt = at
852	}
853	
854	// settle 在全部设备到达终态时结束活动：全部成功则成功，否则失败。
855	// 即使回滚成功，设备也不是 succeeded，活动仍为失败。
856	func (s *Store) settle(c *campaignState, at time.Time) {
857		allSucceeded := true
858		for _, cd := range c.Devices {
859			if !isTerminal(cd.Status) {
860				return
861			}
862			if cd.Status != DeviceSucceeded {
863				allSucceeded = false
864			}
865		}
866		c.Ended = true
867		c.EndedAt = at
868		if allSucceeded {
869			c.Status = CampaignSucceeded
870		} else {
871			c.Status = CampaignFailed
872		}
873	}
874	
875	func isTerminal(status string) bool {
876		switch status {
877		case DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
878			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
879			return true
880		default:
881			return false
882		}
883	}
884	
885	// AdvanceCampaign 用调用方给出的当前时间推进活动：到达截止时间时把未结束
886	// 设备全部记为超时并结束活动。时间缺失或相对已接受时间倒退时拒绝且不改状态。
887	// 未到截止时间或活动已结束时为空操作。
888	func (s *Store) AdvanceCampaign(campaignID string, at time.Time) error {
889		s.mu.Lock()
890		defer s.mu.Unlock()
891		if err := s.checkOpen(); err != nil {
892			return err
893		}
894		c, err := s.lookupCampaign(campaignID)
895		if err != nil {
896			return err
897		}
898		if at.IsZero() {
899			return ErrInvalidTime
900		}
901		if at.Before(c.LastTime) {
902			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
903		}
904		if c.Ended {
905			return nil
906		}
907		if at.Before(c.Deadline) {
908			// 仅推进时间基线也持久化，使重开后的倒退判断仍然有效。
909			return s.commit(func() error { c.LastTime = at; return nil })
910		}
911		return s.commit(func() error {
912			c.LastTime = at
913			s.applyTimeout(c, at)
914			return nil
915		})
916	}
917	
918	func (s *Store) lookupCampaign(campaignID string) (*campaignState, error) {
919		if campaignID == "" {
920			return nil, ErrInvalidCampaignID
921		}
922		c, ok := s.campaigns[campaignID]
923		if !ok {
924			return nil, fmt.Errorf("%w: %s", ErrCampaignNotFound, campaignID)
925		}
926		return c, nil
927	}
928	
929	func (s *Store) lookupCampaignDevice(campaignID, deviceID string) (*campaignState, *campaignDevice, error) {
930		c, err := s.lookupCampaign(campaignID)
931		if err != nil {
932			return nil, nil, err
933		}
934		if deviceID == "" {
935			return nil, nil, ErrInvalidDeviceID
936		}
937		i, ok := c.index[deviceID]
938		if !ok {
939			return nil, nil, fmt.Errorf("%w: %s", ErrDeviceNotInCampaign, deviceID)
940		}
941		return c, c.Devices[i], nil
942	}
943	
944	// DeviceStatusView 是一台设备在活动中的状态快照。
945	type DeviceStatusView struct {
946		DeviceID string
947		Batch    int
948		// Status 取 Device* 状态常量，含等待回滚、正在回滚、回滚成功、
949		// 回滚失败与回滚阶段超时。
950		Status string
951		// Phase 是设备当前停留或失败的阶段（download/install/rollback）。
952		Phase string
953		// Reason 是失败、超时或未执行（skipped）的原因；成功时为空。
954		Reason string
955		// At 是进入当前状态的时间。
956		At time.Time
957		// DownloadID/InstallID/RollbackID 是各阶段操作的稳定标识。
958		DownloadID string
959		InstallID  string
960		RollbackID string
961		// RollbackTarget 是开启回滚时首次领取下载锁定的回滚目标版本；未锁定为空。
962		RollbackTarget string
963		// InstallFailReason/InstallFailAt 是已接受的安装失败的原因与时间，
964		// 进入回滚后仍保留原值，便于与回滚结果分别查看。
965		InstallFailReason string
966		InstallFailAt     time.Time
967		// RollbackResult 表示是否已接受回滚结果。
968		RollbackResult bool
969		// RollbackSuccess 表示已接受的回滚结果是否成功。
970		RollbackSuccess bool
971		// RollbackReason/RollbackAt 是回滚结果（成功或失败）的原因与时间。
972		RollbackReason string
973		RollbackAt     time.Time
974	}
975	
976	// BatchView 是一个批次内所有设备的状态，按提交次序排列。
977	type BatchView struct {
978		Index   int
979		Devices []DeviceStatusView
980	}
981	
982	// CampaignView 是分批升级活动的只读快照。
983	type CampaignView struct {
984		ID            string
985		Operator      string
986		TargetVersion string
987		CreatedAt     time.Time
988		BatchSize     int
989		WindowStart   time.Time
990		WindowEnd     time.Time
991		Deadline      time.Time
992		// RollbackOnFailure 表示该活动是否开启安装失败回滚。
993		RollbackOnFailure bool
994		// Status 取 Campaign* 状态常量。
995		Status  string
996		Ended   bool
997		EndedAt time.Time
998		// Devices 按提交次序给出每台设备的状态。
999		Devices []DeviceStatusView
1000		// Batches 按批次号分组，保留设备提交次序。
1001		Batches []BatchView
1002		// Results 是按接受顺序排列的结果历史（重复提交不产生新记录）。
1003		Results []ResultRecord
1004	}
1005	
1006	// GetCampaign 查询活动：创建者、目标版本、每批设备状态、
1007	// 失败或超时原因及结果历史。返回数据为独立副本。
1008	func (s *Store) GetCampaign(campaignID string) (CampaignView, error) {
1009		s.mu.Lock()
1010		defer s.mu.Unlock()
1011		if err := s.checkOpen(); err != nil {
1012			return CampaignView{}, err
1013		}
1014		c, err := s.lookupCampaign(campaignID)
1015		if err != nil {
1016			return CampaignView{}, err
1017		}
1018		v := CampaignView{
1019			ID:                c.ID,
1020			Operator:          c.Operator,
1021			TargetVersion:     c.Target,
1022			CreatedAt:         c.CreatedAt,
1023			BatchSize:         c.BatchSize,
1024			WindowStart:       c.WindowStart,
1025			WindowEnd:         c.WindowEnd,
1026			Deadline:          c.Deadline,
1027			RollbackOnFailure: c.RollbackOnFailure,
1028			Status:            c.Status,
1029			Ended:             c.Ended,
1030			EndedAt:           c.EndedAt,
1031			Results:           make([]ResultRecord, len(c.Results)),
1032		}
1033		copy(v.Results, c.Results)
1034		for _, cd := range c.Devices {
1035			dv := DeviceStatusView{
1036				DeviceID:       cd.DeviceID,
1037				Batch:          cd.Batch,
1038				Status:         cd.Status,
1039				Phase:          cd.Phase,
1040				Reason:         cd.Reason,
1041				At:             cd.At,
1042				DownloadID:     cd.Download.ID,
1043				InstallID:      cd.Install.ID,
1044				RollbackID:     cd.Rollback.ID,
1045				RollbackTarget: cd.RollbackTarget,
1046			}
1047			// 安装失败原因与时间独立保留，进入回滚后也不被回滚结果覆盖。
1048			if cd.Install.HasResult && !cd.Install.Success {
1049				dv.InstallFailReason = cd.Install.Reason
1050				dv.InstallFailAt = cd.Install.At
1051			}
1052			// 回滚结果的原因与时间单独呈现。
1053			if cd.Rollback.HasResult {
1054				dv.RollbackResult = true
1055				dv.RollbackSuccess = cd.Rollback.Success
1056				dv.RollbackReason = cd.Rollback.Reason
1057				dv.RollbackAt = cd.Rollback.At
1058			}
1059			v.Devices = append(v.Devices, dv)
1060			for len(v.Batches) <= cd.Batch {
1061				v.Batches = append(v.Batches, BatchView{Index: len(v.Batches)})
1062			}
1063			v.Batches[cd.Batch].Devices = append(v.Batches[cd.Batch].Devices, dv)
1064		}
1065		return v, nil
1066	}
1067	
1068	// DeviceWork 是设备当前版本与待执行操作的查询结果。
1069	type DeviceWork struct {
1070		DeviceID string
1071		Version  string
1072		Online   bool
1073		// CampaignID 是设备当前所在的未结束活动；没有时为空。
1074		CampaignID string
1075		// Pending 是设备仍待完成的操作（至多一个）：已领取未完成或下一阶段可领取。
1076		// 等待回滚时为尚未领取的回滚操作，其 TargetVersion 给出锁定的回滚目标。
1077		Pending *Operation
1078		// PendingClaimed 表示 Pending 是否已领取（未领取的安装或回滚仍须等维护窗口）。
1079		PendingClaimed bool
1080	}
1081	
1082	// GetDeviceWork 查询设备当前版本及其待执行操作。
1083	func (s *Store) GetDeviceWork(deviceID string) (DeviceWork, error) {
1084		s.mu.Lock()
1085		defer s.mu.Unlock()
1086		if err := s.checkOpen(); err != nil {
1087			return DeviceWork{}, err
1088		}
1089		d, err := s.lookup(deviceID)
1090		if err != nil {
1091			return DeviceWork{}, err
1092		}
1093		w := DeviceWork{DeviceID: deviceID, Version: d.Version, Online: d.Online}
1094		for id, c := range s.campaigns {
1095			if c.Ended {
1096				continue
1097			}
1098			i, ok := c.index[deviceID]
1099			if !ok {
1100				continue
1101			}
1102			cd := c.Devices[i]
1103			w.CampaignID = id
1104			if out := outstandingOp(c, cd); out != nil {
1105				w.Pending = out
1106				w.PendingClaimed = true
1107			} else if cd.Status == DeviceAwaitingRollback {
1108				// 回滚待领取：显示回滚目标，标记为尚未领取。
1109				w.Pending = &Operation{
1110					ID:            cd.Rollback.ID,
1111					CampaignID:    c.ID,
1112					DeviceID:      deviceID,
1113					Kind:          StageRollback,
1114					TargetVersion: cd.RollbackTarget,
1115				}
1116				w.PendingClaimed = false
1117			} else if !isTerminal(cd.Status) {
1118				kind := StageDownload
1119				id := cd.Download.ID
1120				if cd.Download.HasResult {
1121					kind, id = StageInstall, cd.Install.ID
1122				}
1123				w.Pending = &Operation{ID: id, CampaignID: c.ID, DeviceID: deviceID, Kind: kind}
1124				w.PendingClaimed = false
1125			}
1126			break
1127		}
1128		return w, nil
1129	}
1130	
1131	// ListUpgrades 返回已登记的全部升级目标版本，按目标版本字典序排列。
1132	func (s *Store) ListUpgrades() ([]VersionSpec, error) {
1133		s.mu.Lock()
1134		defer s.mu.Unlock()
1135		if err := s.checkOpen(); err != nil {
1136			return nil, err
1137		}
1138		out := make([]VersionSpec, 0, len(s.versions))
1139		for _, v := range s.versions {
1140			out = append(out, VersionSpec{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)})
1141		}
1142		sort.Slice(out, func(i, j int) bool { return out[i].Target < out[j].Target })
1143		return out, nil
1144	}
